-- =====================================================================
-- 488_tprm_third_parties_engagements_rollback.sql
--
-- Reverses 488 (third parties, engagements, inherent risk).
--   Drops the 488 procedures and functions; removes sample records; drops
--   the 488 tables when they are empty and 489 has been rolled back.
--
-- Turn the API / Web change off first (or deploy the previous build): the
-- TPRM screens call the procedures this drops. Roll back in reverse
-- order: 490, 489, 488, 487, 486.
-- Generated by tools/tprm/gen_rollbacks.py from the objects 488 creates.
-- SAFE TO RE-RUN. ASCII-only.
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET NOEXEC OFF;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_risk_assessment_complete;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_risk_answers_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_risk_assessment_get;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_risk_assessment_start;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_risk_score;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_link_action;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_link_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_engagement_discover;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_scope_item_remove;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_scope_item_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_engagement_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_engagement_get;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_engagement_list;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_sample_load;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_vendor_import;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_vendor_discovery;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_third_party_status;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_third_party_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_third_party_get;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_third_party_list;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_lookups;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_third_party_sync_status;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_engagement_event;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_engagement_signals;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_meaning_code;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_third_party_matches;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_normalize_name;
GO

-- Sample records (BRD 6) are removed first: they are not organization data.
IF OBJECT_ID('grac_practice.tprm_third_party','U') IS NOT NULL AND OBJECT_ID('grac_practice.tprm_dd_assessment','U') IS NULL
   AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_third_party WHERE is_sample = 0)
BEGIN
    DELETE d FROM grac_practice.tprm_risk_assessment_dimension d JOIN grac_practice.tprm_risk_assessment a ON a.assessment_id = d.assessment_id;
    DELETE FROM grac_practice.tprm_risk_assessment_answer;
    UPDATE grac_practice.tprm_engagement SET current_risk_assessment_id = NULL;
    DELETE FROM grac_practice.tprm_risk_assessment;
    DELETE FROM grac_practice.tprm_engagement_history;
    DELETE FROM grac_practice.tprm_exposure_snapshot;
    DELETE FROM grac_practice.tprm_engagement_link;
    DELETE FROM grac_practice.tprm_engagement_scope;
    DELETE FROM grac_practice.tprm_engagement;
    DELETE FROM grac_practice.tprm_third_party_status_history;
    DELETE FROM grac_practice.tprm_third_party_contact;
    DELETE FROM grac_practice.tprm_third_party_category;
    DELETE FROM grac_practice.tprm_third_party;
    IF OBJECT_ID('grac_practice.tprm_custom_field_value','U') IS NOT NULL
        DELETE FROM grac_practice.tprm_custom_field_value WHERE entity_code IN (N'THIRD_PARTY', N'ENGAGEMENT');
    PRINT '488 rollback: sample records removed.';
END
GO

-- Tables: dropped only when they hold no rows and 489 is rolled back; otherwise
-- they are kept (the procedures are gone, the data is not) and the
-- script says so. Delete the rows deliberately first to drop them.
IF OBJECT_ID('grac_practice.tprm_third_party','U') IS NOT NULL
BEGIN
    IF OBJECT_ID('grac_practice.tprm_dd_assessment','U') IS NULL
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_third_party)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_third_party_category)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_third_party_contact)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_third_party_status_history)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_engagement)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_engagement_scope)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_engagement_link)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_exposure_snapshot)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_engagement_history)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_risk_assessment)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_risk_assessment_answer)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_risk_assessment_dimension)
    BEGIN
        DECLARE @fk NVARCHAR(MAX) = N'';
        SELECT @fk = @fk + N'ALTER TABLE grac_practice.' + QUOTENAME(OBJECT_NAME(fk.parent_object_id))
                         + N' DROP CONSTRAINT ' + QUOTENAME(fk.name) + N';'
        FROM sys.foreign_keys fk
        WHERE OBJECT_SCHEMA_NAME(fk.parent_object_id) = N'grac_practice'
          AND OBJECT_NAME(fk.parent_object_id) IN (N'tprm_third_party', N'tprm_third_party_category', N'tprm_third_party_contact', N'tprm_third_party_status_history', N'tprm_engagement', N'tprm_engagement_scope', N'tprm_engagement_link', N'tprm_exposure_snapshot', N'tprm_engagement_history', N'tprm_risk_assessment', N'tprm_risk_assessment_answer', N'tprm_risk_assessment_dimension');
        EXEC sp_executesql @fk;
        DROP TABLE IF EXISTS grac_practice.tprm_risk_assessment_dimension;
        DROP TABLE IF EXISTS grac_practice.tprm_risk_assessment_answer;
        DROP TABLE IF EXISTS grac_practice.tprm_risk_assessment;
        DROP TABLE IF EXISTS grac_practice.tprm_engagement_history;
        DROP TABLE IF EXISTS grac_practice.tprm_exposure_snapshot;
        DROP TABLE IF EXISTS grac_practice.tprm_engagement_link;
        DROP TABLE IF EXISTS grac_practice.tprm_engagement_scope;
        DROP TABLE IF EXISTS grac_practice.tprm_engagement;
        DROP TABLE IF EXISTS grac_practice.tprm_third_party_status_history;
        DROP TABLE IF EXISTS grac_practice.tprm_third_party_contact;
        DROP TABLE IF EXISTS grac_practice.tprm_third_party_category;
        DROP TABLE IF EXISTS grac_practice.tprm_third_party;
        PRINT '488 rollback: tables dropped.';
    END
    ELSE
        PRINT '488 rollback: third-party / engagement data exists (or 489 is still in place) -- tables kept.';
END
GO

PRINT '488 rollback complete.';
GO
